(function(){
  'use strict';
  let bundle=null;const base=new URL('./vendor/ocr/',document.baseURI);
  function load(){if(globalThis.Tesseract)return Promise.resolve(globalThis.Tesseract);if(!bundle)bundle=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('tesseract.min.js',base).href;script.onload=()=>resolve(globalThis.Tesseract);script.onerror=()=>{bundle=null;reject(new Error('ocrUnavailable'));};document.head.appendChild(script);});return bundle;}
  function prepare(image){const w=image.width,h=image.height;if(w*h>20000000)throw new Error('imageTooLarge');const ratio=Math.min(3,4000/Math.max(w,h),Math.sqrt(14000000/(w*h))),canvas=document.createElement('canvas');canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);const c=canvas.getContext('2d');if(!c)throw new Error('ocrUnavailable');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(image,0,0,canvas.width,canvas.height);return canvas;}
  async function recognize(image,onProgress){
    const api=await load(),canvas=prepare(image);let worker;
    function crop(bbox,right,threshold=false){const x=Math.max(0,Math.floor(bbox.x0-12)),y=Math.max(0,Math.floor(bbox.y0-12)),out=document.createElement('canvas');out.width=Math.max(1,Math.min(canvas.width,right||bbox.x1+12)-x);out.height=Math.min(canvas.height-y,Math.ceil(bbox.y1-bbox.y0+24));const c=out.getContext('2d');c.drawImage(canvas,x,y,out.width,out.height,0,0,out.width,out.height);if(threshold){const px=c.getImageData(0,0,out.width,out.height);for(let i=0;i<px.data.length;i+=4){const v=(px.data[i]+px.data[i+1]+px.data[i+2])/3<210?0:255;px.data[i]=px.data[i+1]=px.data[i+2]=v;}c.putImageData(px,0,0);}return out;}
    function tableImage(rect){const out=document.createElement('canvas');out.width=rect.width;out.height=rect.height;const c=out.getContext('2d');c.drawImage(canvas,rect.left,rect.top,rect.width,rect.height,0,0,rect.width,rect.height);const px=c.getImageData(0,0,out.width,out.height),sample=[];for(let i=0;i<px.data.length;i+=400)sample.push(Math.min(px.data[i],px.data[i+1],px.data[i+2]));sample.sort((a,b)=>a-b);const paper=sample[Math.floor(sample.length*.9)]||255,threshold=Math.min(210,paper-30);for(let i=0;i<px.data.length;i+=4){const v=Math.min(px.data[i],px.data[i+1],px.data[i+2])<threshold?0:255;px.data[i]=px.data[i+1]=px.data[i+2]=v;}c.putImageData(px,0,0);return out;}
    try{worker=await api.createWorker(['eng','chi_sim'],1,{workerPath:new URL('worker.min.js',base).href,corePath:base.href,langPath:base.href.replace(/\/$/,''),cacheMethod:'none',logger:m=>onProgress?.(m.progress||0),errorHandler:()=>{}});return await CatOCRTable.recognize(worker,canvas,{width:canvas.width,height:canvas.height,tableImage,headerImage:b=>crop(b,null,true),cropRow:(b,right)=>crop(b,right).toDataURL('image/png')});}catch{throw new Error('ocrUnavailable');}finally{if(worker)await worker.terminate();canvas.width=canvas.height=0;}
  }
  async function readImage(data,onProgress){const url=URL.createObjectURL(new Blob([data])),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('badData'));img.src=url;});return await recognize(img,onProgress);}finally{URL.revokeObjectURL(url);}}
  window.CatOCR={readImage,readCanvas:recognize};
})();
